function teleport(where){const spots={home:[0,0,3.8],map:[0,0,3.8],words:[0,0,3.8]};const p=spots[where];$('rig').setAttribute('position',p.join(' '));$('rig').object3D.rotation.set(0,0,0);const camera=$('camera');camera.setAttribute('position','0 1.65 0');const look=camera.components['look-controls'];if(look){look.yawObject.rotation.y=0;look.pitchObject.rotation.x=0}notify(where==='home'?'Returned to the observatory entrance.':where==='map'?'Globe viewpoint. Select a glowing marker.':'Vocabulary viewpoint. Select a word to listen.')}
