function drawLens(point){if(window.globiquest?.magicLens){window.globiquest.magicLens.requestCapture();return}if(!lensImage.complete||!lensImage.naturalWidth)return;const d=destinations[state.place];let lat=d[3],lon=d[4];if(point){lat=Math.asin(Math.max(-1,Math.min(1,point.y/point.length())))*180/Math.PI;lon=Math.atan2(-point.z,point.x)*180/Math.PI}const ctx=lensContext;ctx.fillStyle='#e9eff7';ctx.fillRect(0,0,512,512);const iw=lensImage.naturalWidth,ih=lensImage.naturalHeight,sw=iw/(3*state.zoom),sh=sw;const cx=(lon+180)/360*iw,cy=(90-lat)/180*ih;ctx.save();ctx.beginPath();ctx.arc(256,256,252,0,Math.PI*2);ctx.clip();for(let offset=-iw;offset<=iw;offset+=iw)ctx.drawImage(lensImage,cx-sw/2+offset,Math.max(0,Math.min(ih-sh,cy-sh/2)),sw,sh,0,0,512,512);ctx.fillStyle='rgba(217,237,248,.4)';ctx.fillRect(0,0,512,512);ctx.strokeStyle='#ffffff88';ctx.lineWidth=1;for(let i=64;i<512;i+=64){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,512);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(512,i);ctx.stroke()}ctx.strokeStyle='#007aff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(256,256,15,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f5f7fbee';ctx.fillRect(0,410,512,102);ctx.textAlign='center';ctx.fillStyle='#1d1d1f';ctx.font='22px sans-serif';ctx.fillText(point?'MAP INSPECTOR':d[0].toUpperCase(),256,449);ctx.font='17px sans-serif';ctx.fillText(`${lat.toFixed(2)}°, ${lon.toFixed(2)}° · ${state.zoom}×`,256,480);ctx.restore();lensTexture.needsUpdate=true;const mesh=$('lensGlass').getObject3D('mesh');if(mesh){mesh.material.map=lensTexture;mesh.material.needsUpdate=true}}
lensImage.onload=()=>{if(initialized)drawLens()};
function cycleZoom(){if(window.globiquest?.magicLens){window.globiquest.magicLens.zoom(.5);return}state.zoom=state.zoom===4?2:state.zoom+1;drawLens();renderNav();notify('Magnifier '+state.zoom+'× · Grip to hold; aim at globe to inspect.')}
function holdLens(hand){if(window.globiquest.workspace!=='lens')return;const lens=$('lens');if(state.lensHeld)return;state.lensHeld=true;hand.object3D.attach(lens.object3D);lens.object3D.position.set(0,.04,-.32);lens.object3D.rotation.set(0,0,0);lens.object3D.scale.setScalar(.65);notify('Magnifier held. Aim your controller at the globe; release grip to place it.')}
function releaseLens(){if(!state.lensHeld)return;const lens=$('lens');scene.object3D.attach(lens.object3D);lens.object3D.scale.setScalar(1);lens.dataset.userPlaced='true';state.lensHeld=false}
function moveLens(){if(state.lensHeld){releaseLens();return}const pos=$('lens').object3D.position;pos.x=pos.x>0?-1.1:1.1;pos.y=1.55;pos.z=1.1;drawLens();notify('Lens moved. Select its glass to change zoom; Quest grip to hold.')}
const raycaster=new THREE.Raycaster(),origin=new THREE.Vector3(),direction=new THREE.Vector3();let lensTick=0;
function updateLensFromAim(){if(performance.now()-lensTick<80)return;lensTick=performance.now();const hand=$('lens').object3D.parent;hand.getWorldPosition(origin);hand.getWorldDirection(direction);direction.negate();raycaster.set(origin,direction);const mesh=$('planet').getObject3D('mesh');if(!mesh)return;const hits=raycaster.intersectObject(mesh);if(hits.length){const p=$('earthRoot').object3D.worldToLocal(hits[0].point.clone());drawLens(p)}}
