async function enterVR(){music.unlock().catch(()=>{});if(scene.is('vr-mode')){await scene.exitVR();return}try{if(!navigator.xr||!await navigator.xr.isSessionSupported('immersive-vr')){notify('This browser has no immersive headset session. On a computer, use Hand lab to simulate gestures; Quest users should open this URL in Quest Browser.');return}if(!window.globiquest.iwsdk){notify('Preparing XR. Please try again in a moment.');return}await scene.enterVR()}catch{notify('VR could not start. Check headset permissions, then retry.')}}
